addEventListener('qskvoiceschanged',()=>{if($('live-voiceName'))$('live-voiceName').innerHTML=voiceOptions();updateVoiceControls();render(true);});

function presentationControls(){const checks=[['sound','Sound and narration'],['spokenOptions','Spoken option / selection cues'],['readQuestions','Read question automatically before choices'],['coinAnimation','Coin toss animation'],['questionAnimation','Question / answer entrances'],['winnerAnimation','Winner entrance'],['rewards','Point gain / loss effects'],['confetti','Confetti'],['intro','Opening announcement']];return '<label for="live-motion">Animation style</label><select id="live-motion" data-presentation="motion">'+[['cinematic','Cinematic quiz show'],['gentle','Gentle classroom'],['none','No decorative motion']].map(([value,label])=>'<option value="'+value+'" '+(presentation.motion===value?'selected':'')+'>'+label+'</option>').join('')+'</select><div class="row"><label for="live-volume">Volume (%)</label><input id="live-volume" data-presentation="volume" type="range" min="0" max="100" step="1" value="'+presentation.volume+'"><output id="live-volume-label" for="live-volume">'+presentation.volume+'%</output></div>'+voiceControls()+checks.map(([key,label])=>'<label class="live-setting" for="live-'+key+'"><input id="live-'+key+'" data-presentation="'+key+'" type="checkbox" '+(presentation[key]?'checked':'')+'> '+label+'</label>').join('');}
function applyPresentation(){document.querySelectorAll('.score-pop').forEach(n=>n.classList.remove('score-pop'));lessMotion=presentation.motion==='none'||Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)').matches);motion?.cancel();penalty?.clear();stopAudioQueue();visualScores.clear();pendingCelebrations=[];muted=!presentation.sound;volume=presentation.volume/100;$('stage').classList.toggle('low-motion',lessMotion);$('stage').dataset.motion=lessMotion?'none':presentation.motion;window.BioDNAView?.dispose?.();window.BioDNAView=null;document.querySelectorAll('.dna3d-surface').forEach(n=>n.remove());document.querySelector('.turn-lane')?.classList.remove('dna3d-ready');const track=$('dna-track');if(track)track.style.visibility='';configureMotion();attachDNA();readReadyAt=revealReadyAt=0;readToken=revealToken='';try{localStorage.setItem(key+'.presentation',JSON.stringify(presentation));}catch(_){}render(true);updateSound();audioBus?.configureSpeech(presentation);updateVoiceControls();if($('live-volume-label'))$('live-volume-label').textContent=presentation.volume+'%';}
function settings(){openModal('Presentation settings','<div class="settings-grid"><section class="settings-card"><h2>Sound and animation</h2>'+presentationControls()+'<p class="status-note">Changes apply immediately and are kept in this browser when saving is available. Save a resume copy to carry these settings to another computer. Scores and rules stay consistent; play remains paused while this panel is open.</p><div class="row"><button data-ui="testSound">Test sound</button></div><p id="sound-status"></p></section><section class="settings-card"><h2>Host and recovery</h2><div class="row"><button data-ui="previewWinnerBio">Preview '+esc(teamName('Bio'))+' finale</button><button data-ui="previewWinnerVista">Preview '+esc(teamName('Vista'))+' finale</button></div><div class="row"><button data-ui="host">Host tools</button><button data-ui="saveCopy">Save resume copy</button></div><p class="status-note" id="save-status">'+esc(recoveryNote)+'</p><p class="status-note">Enter / Space: visible main action. A–D: select and lock the clock. P: pause / resume. Esc closes a panel or exits full screen.</p><h2>About Quiz Show Kit</h2><p class="status-note">Curated for Parul University Goa · Open to every teacher.<br>Created by Namdev Shirodkar, a Parul University Goa student.<br>First iteration of an extensible teaching toolkit. Any subject, department or college can adapt it.</p></section></div>'+captureHTML()+'<p class="status-note">'+esc(KIT.event.organization)+(KIT.event.date?' · '+esc(KIT.event.date):'')+'</p>');updateSound();updateVoiceControls();}
function host(){openModal('Host tools','<p>Live play stays paused while this panel is open. The host recognises speakers and manually enforces the two-answer limit.</p><div class="tabs"><button data-ui="scoreTools">Scores / replacement</button><button data-ui="eventLog">Event log</button><button data-ui="reviewGate">Review / credits…</button></div><div class="host-section"><div class="row"><button data-ui="saveCopy">Save resume copy</button><button data-ui="reset" class="danger">Start fresh…</button></div><p>'+esc(recoveryNote)+'</p><p>A resume copy is another complete HTML file with this checkpoint. Reopening offers Resume with a paused clock. The browser cannot silently overwrite the original file.</p><p>For a disputed question, use a faculty-reviewed unused reserve with equivalent difficulty and timing. Its score changes and lifeline use are rolled back; the scheduled primary team stays the same.</p></div>','host');}
function scoreTools(){const card=BioEngine.view(state,now()).question,reserves=Q.filter(x=>x.status==='reserve'&&!(state.usedReserves||[]).includes(x.id)&&card&&(x.suitableRounds||[x.round]).includes(card.round)&&x.difficulty===card.difficulty&&(x.seconds||15)===(card.seconds||15));openModal('Guarded scoring / faculty replacement','<div class="host-section"><p>A faculty-reviewed reason is required and saved in the event log.</p><div class="row"><label>Team <select id="correction-team"><option value="Bio">'+esc(teamName('Bio'))+'</option><option value="Vista">'+esc(teamName('Vista'))+'</option></select></label><label>Tally <select id="correction-kind"><option value="main">Main</option><option value="tie">Tie-break</option></select></label><label>Score delta <input id="correction-delta" type="number" value="0" step="1" style="width:140px"></label></div><div class="row"><input class="reason" id="correction-reason" placeholder="Reason for score correction"><button data-ui="correctScore">Apply correction…</button></div><h2>Void current question and replace</h2><p>This removes the current question’s score changes and associated lifeline use, while preserving the primary opportunity.</p><div class="row"><select id="reserve">'+reserves.map(x=>'<option value="'+x.id+'">'+esc(x.id)+' · '+esc(x.topic)+'</option>').join('')+'</select><input class="reason" id="replace-reason" placeholder="Faculty-reviewed reason"><button data-ui="replace" '+(!reserves.length||state.kind!=='main'?'disabled':'')+'>Void + use reserve…</button></div>'+(!reserves.length?'<p>No unused reserve matches this question. Keep play paused while faculty review the dispute.</p>':'')+'<button data-ui="host">Back</button></div>','scoreTools');}
function eventLog(){const safe=(state.log||[]).map(x=>{const {participantId,participantAttempts,attempts,...entry}=x;return entry;});openModal('Local event log','<div class="host-section"><p>Confirmed outcomes, score corrections, clock actions and lifeline use are recorded locally. No student identities are collected.</p><pre>'+esc(JSON.stringify(safe,null,2))+'</pre><button data-ui="host">Back</button></div>','eventLog');}
function reviewGate(){openModal('Guarded answer review','<p>This area contains correct answers and source notes. Hide or blank the projection before continuing. The clock stays paused.</p><button data-ui="review" class="primary">Projection hidden · open review</button><button data-ui="host">Cancel</button>','review');}
function review(){openModal('Host-only content review / credits','<div class="host-section"><p>'+Q.length+' cards. Source-check dates are recorded per question where supplied. No references need to load during live play.</p>'+Q.map(q=>'<details><summary>'+esc(q.id)+' · '+esc(q.status)+' · '+esc(q.topic)+' · '+esc(q.difficulty)+'</summary><p>'+esc(q.stem)+'</p><p>'+q.options.map((o,i)=>'ABCD'[i]+': '+esc(o)).join('<br>')+'</p><p><b>Answer '+('ABCD'[optionIndex(q.correct)])+'</b> · '+esc(q.explanation)+'</p><p>'+q.sources.map(s=>s.url?'<a href="'+esc(s.url)+'" target="_blank" rel="noopener">'+esc(s.title)+'</a>':esc(s.title)).join('<br>')+'<br>'+(q.verificationDate?'Source check: '+esc(q.verificationDate):'Needs source review')+(q.visual?'<br>'+esc(q.visual.attribution||'Embedded scientific diagram'):'')+'</p></details>').join('')+'<h2>Embedded assets</h2><pre>'+esc(JSON.stringify(Object.fromEntries(Object.entries(ASSETS).map(([k,v])=>[k,{...v,data:undefined}])),null,2))+'</pre><p>Audio includes embedded CC0 effects, offline letter announcements and original synthesised cues. Animation uses the packaged GSAP and canvas-confetti libraries. System fonts. The offline host file contains its answers; keep it with the host before the event.</p><button data-ui="host">Back</button></div>','review');}
function saveCopy(){if(practice){toast('Return to the official quiz before saving a resume copy.');return;}save();const doc=document.documentElement.cloneNode(true);doc.querySelectorAll('.dna3d-surface,#penalty-layer').forEach(node=>node.remove());const copyLane=doc.querySelector('.turn-lane');copyLane?.classList.remove('dna3d-ready');if(copyLane)delete copyLane.dataset.dnaRenderer;const copyTrack=doc.querySelector('#dna-track');if(copyTrack)copyTrack.style.visibility='';doc.querySelector('#recording-indicator')?.remove();doc.querySelector('#rehearsal-badge')?.remove();doc.querySelector('#kit-config').textContent=JSON.stringify({...KIT,presentation}).replace(/</g,'\\u003c');doc.querySelector('#checkpoint').textContent=JSON.stringify(resume&&state.phase==='intro'?resume:BioEngine.checkpoint(state,now())).replace(/</g,'\\u003c');doc.querySelector('#overlay').innerHTML='';doc.querySelector('#motion-layer').innerHTML='';doc.querySelector('#cinematic-layer').innerHTML='';doc.querySelector('#cinematic-layer').hidden=true;doc.querySelector('#teacher-graphic').hidden=true;doc.querySelector('#toast').hidden=true;const blob=new Blob(['<!doctype html>\n'+doc.outerHTML],{type:'text/html'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=KIT.event.id+'_Quiz_Resume_'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')+'.html';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);cue('save');toast('Resume copy requested. Check the browser Downloads location.');}
