if(u==='skipMotion'){if(motion?.isBusy()){motion.skip();if(!motion.isBusy())render(true);}else{readReadyAt=0;revealReadyAt=0;motion?.finishEntries();motion?.clearRewards();render(true);}return;}if(u==='finishCinema'){motion?.skip();render(true);return;}if(u==='resumeCinema'){motion?.resume();return;}if(motion?.isBusy()&&!['testSound','sound','fullscreen'].includes(u))return;
