const optionPreviewAt=new WeakMap();
function previewOption(node,on){if(!node||node.disabled||modal||motion?.isBusy())return;motion?.hoverOption(node,on);if(on){const last=optionPreviewAt.get(node)??-Infinity;if(now()-last>180){optionPreviewAt.set(node,now());cue('option'+'ABCD'[Number(node.dataset.option)]);}}}
document.addEventListener('pointerover',event=>{const node=event.target.closest?.('[data-option]');if(node&&!node.contains(event.relatedTarget))previewOption(node,true);});
document.addEventListener('pointerout',event=>{const node=event.target.closest?.('[data-option]');if(node&&!node.contains(event.relatedTarget))previewOption(node,false);});
document.addEventListener('focusin',event=>previewOption(event.target.closest?.('[data-option]'),true));
document.addEventListener('focusout',event=>previewOption(event.target.closest?.('[data-option]'),false));

document.addEventListener('input',e=>{const n=e.target,k=n.dataset.presentation;if(!k)return;if(k==='motion'){if(!['cinematic','gentle','none'].includes(n.value))return;presentation.motion=n.value;}else if(k==='volume'){const value=Number(n.value);if(!Number.isInteger(value)||value<0||value>100)return;presentation.volume=value;}else if(k==='optionSpeech'){if(!['smart','letters','full'].includes(n.value))return;presentation[k]=n.value;}else if(k==='voiceName'){if(n.value.length>160||n.value&&!audioBus?.listVoices().some(v=>v.name===n.value))return;presentation[k]=n.value;}else if(k==='voiceLang'){if(n.value.length>35||!(/^[a-z]{2,8}(?:-[a-z0-9]{1,8})*$/i.test(n.value)))return;presentation[k]=n.value;}else if(k==='speechRate'){const value=Number(n.value);if(!Number.isFinite(value)||value<.5||value>2)return;presentation[k]=value;}else if(['sound','spokenOptions','confetti','rewards','intro','coinAnimation','questionAnimation','winnerAnimation','readQuestions'].includes(k))presentation[k]=n.checked;else return;applyPresentation();});
