if(e.key==='Escape'){if(!motion?.isBusy()&&modal)closeModal();return;}
if(motion?.isBusy()){const inside=e.target.closest?.('#cinematic-layer');if(e.key==='Tab'){const buttons=Array.from(document.querySelectorAll('#cinematic-layer button:not(:disabled),#recording-indicator:not([hidden]) [data-recorder-stop]:not(:disabled)'));if(buttons.length){e.preventDefault();const current=buttons.indexOf(document.activeElement),next=(current+(e.shiftKey?-1:1)+buttons.length)%buttons.length;buttons[next].focus();}}else if((e.key===' '||e.key==='Enter')&&!inside&&!['testSound','sound','fullscreen'].includes(e.target.closest?.('button')?.dataset.ui))e.preventDefault();return;}
if(modal){const inside=e.target.closest?.('#overlay');if(e.key==='Tab'){const controls=Array.from(document.querySelectorAll('#overlay button:not(:disabled),#overlay input:not(:disabled),#overlay select:not(:disabled),#overlay textarea:not(:disabled),#overlay a[href],#overlay summary,#recording-indicator:not([hidden]) [data-recorder-stop]:not(:disabled)')).filter(node=>!node.closest('[hidden]')&&(!node.closest('details:not([open])')||node.tagName==='SUMMARY'));if(controls.length){e.preventDefault();const current=controls.indexOf(document.activeElement),next=(current+(e.shiftKey?-1:1)+controls.length)%controls.length;controls[next].focus();}}else if((e.key===' '||e.key==='Enter')&&!inside&&!['testSound','sound','fullscreen'].includes(e.target.closest?.('button')?.dataset.ui))e.preventDefault();return;}
const k=e.key.toUpperCase();if(k.length===1&&'ABCD'.includes(k)){if(['answering','acknowledged'].includes(state.phase)&&!state.timer?.paused&&!state.lifelineActive){e.preventDefault();const option='ABCD'.indexOf(k);if((BioEngine.view(state,now()).blockedOptions||[]).includes(option)){toast('That option was already tried. Choose another answer.');return;}act('STAGE',{option});}return;}
if(k==='P'){e.preventDefault();if(['answering','acknowledged','passTransition','optionsIntro'].includes(state.phase))act(state.timer?.paused?'RESUME':'PAUSE');return;}
